param([string]$Serial='7b670025',[string]$NormalApk,[string]$ThrowingApk,[string]$NormalSha256,[string]$ThrowingSha256)
$ErrorActionPreference='Stop';if($Serial -ne '7b670025'){throw 'serial must be 7b670025'};$adb='D:/Company/Install/Android/SDK/platform-tools/adb.exe';$root=Split-Path $PSScriptRoot -Parent;$report=Join-Path $root "build/reports/task55/$Serial";New-Item -ItemType Directory -Force $report|Out-Null;. (Join-Path $PSScriptRoot 'task47-adb-helper.ps1');function A([string[]]$x){Invoke-AdbBounded -Adb $adb -Serial $Serial -CommandArgs $x -TimeoutSec 30 -ReportDir $report};function V($t,$k){$m=@($t -split "`r?`n"|?{$_ -match '^'+[regex]::Escape($k)+'='});if($m.Count-ne 1){throw "bad $k"};$m[0].Substring($k.Length+1)};function Run($action,$extra=@()){ $id=[guid]::NewGuid().ToString('N');$args=@('shell','am','start','-W','-n','com.example.appsandbox/.automation.Task55Api31Activity','--es','runId',$id,'--es','action',$action)+$extra;A $args|Out-Null;$p="files/task55-$id.result";for($i=0;$i-lt 80;$i++){ $t=A @('shell','run-as','com.example.appsandbox','cat',$p);if((V $t 'status') -eq 'FINAL'){$t|Set-Content (Join-Path $report "$action-$id.txt");return $t};Start-Sleep -Milliseconds 250};throw "timeout $action"}
if((A @('shell','getprop','ro.build.version.sdk')).Trim() -ne '31'){throw 'wrong API'};if(!(Test-Path $NormalApk)-or!(Test-Path $ThrowingApk)){throw 'APK paths required'};A @('install','-r',(Join-Path $root 'app/build/outputs/apk/debug/app-debug.apk'))|Out-Null;A @('shell','pm','clear','com.example.appsandbox')|Out-Null;A @('push',$NormalApk,'/data/local/tmp/task55-normal.apk')|Out-Null;A @('push',$ThrowingApk,'/data/local/tmp/task55-throwing.apk')|Out-Null;A @('shell','run-as','com.example.appsandbox','mkdir','-p','files')|Out-Null;A @('shell','run-as','com.example.appsandbox','cp','/data/local/tmp/task55-normal.apk','files/task55-normal.apk')|Out-Null;A @('shell','run-as','com.example.appsandbox','cp','/data/local/tmp/task55-throwing.apk','files/task55-throwing.apk')|Out-Null
